// after: 'now it's a reusable headless primitive'
+function useDropdown<T>(items: T[]) {
+  const [open, setOpen] = useState(false);
+  const [active, setActive] = useState(0);
+  const getToggleProps = () => ({ onClick: () => setOpen((o) => !o), "aria-expanded": open });
+  const getItemProps = ({ index }: { index: number }) => ({
+    onMouseEnter: () => setActive(index),
+    "data-active": index === active,
+  });
+  return { open, active, getToggleProps, getItemProps };
+}
+function AccountMenu({ user }: { user: User }) {
+  const items = [{ href: "/profile", label: "Profile" }, { href: "/logout", label: "Log out" }];
+  const { open, getToggleProps, getItemProps } = useDropdown(items);
+  return (
+    <div className="acct">
+      <button {...getToggleProps()}>{user.name}</button>
+      {open && (
+        <ul className="acct-menu">
+          {items.map((it, i) => (
+            <li key={it.href} {...getItemProps({ index: i })}><a href={it.href}>{it.label}</a></li>
+          ))}
+        </ul>
+      )}
+    </div>
+  );
+}
